                std::free(_data);
                _data = InvalidAddress;
                _size = 0;
            }
        }

#endif

    public:
#ifndef FUZZING_HEADERS_NO_IMPL
        CoreType* data(void) {
            access_hook();
            return _data;
        }

        size_t size(void) const {
            access_hook();
            return _size;
        }
#endif

        Container(void)
#ifndef FUZZING_HEADERS_NO_IMPL
